(690,'k,733,k','鸟嘴加农炮','先加热鸟嘴后再进行攻击.鸟嘴在加热时对手触碰的话，就会使其灼伤.',80,100,15,0,'飞行','物攻'),
(691,'k,784,k','鳞片噪音','摩擦全身鳞片，发出响亮的声音进行攻击.攻击后自己的防御会降低.',80,110,5,0,'龙','特攻'),
(692,'k,103,357,k','龙锤','将身体当作锤子，向对手发动袭击，给予伤害.',65,90,15,0,'龙','物攻'),
(693,'k,147,148,149,371,372,373,383,384,386,443,444,445,610,611,612,633,634,635,641,642,643,644,645,646,656,657,658,659,660,679,680,681,686,687,688,689,694,695,696,697,704,705,706,708,709,710,711,727,739,740,759,760,765,766,776,781,783,784,787,793,796,797,799,800,805,807,809,812,819,820,843,844,850,851,853,857,858,865,867,874,878,879,880,882,888,890,893,k','狂舞挥打','用自己的身体狂舞挥打，给予对手伤害。 ',10,60,20,0,'恶','物攻'),
(694,'k,99999,k','极光幕','在５回合内减弱物理和特殊的伤害.只有冰雹时才能使出.',150,0,20,0,'冰','其他'),
(695,'k,99999,k','遮天蔽日暗影箭','通过Ｚ力量制造出无数箭的狙射树枭将全力射穿对手进行攻击.',100,180,1,0,'幽灵','物攻'),
(696,'k,99999,k','极恶飞跃粉碎击','通过Ｚ力量得到强壮肉体的炽焰咆哮虎将全力撞向对手进行攻击.',100,180,1,0,'恶','物攻'),
(697,'k,99999,k','海神庄严交响乐','通过Ｚ力量召唤大量水的西狮海壬将全力攻击对手.',100,195,1,0,'水','特攻'),
(698,'k,99999,k','巨人卫士・阿罗拉','通过Ｚ力量得到阿罗拉之力的土地神宝可梦将全力进行攻击.对手的剩余ＨＰ会减少很多.',150,0,1,0,'妖精','特攻'),
(699,'k,99999,k','七星夺魂腿','得到Ｚ力量的玛夏多将全力使出拳头和脚踢的连续招式叩打对手.',100,195,1,0,'幽灵','物攻'),
(700,'k,99999,k','驾雷驭电戏冲浪','得到Ｚ力量的阿罗拉地区的雷丘将全力进行攻击.从而让对手陷入麻痹状态.',100,175,1,0,'电','特攻'),
(701,'k,99999,k','认真起来大爆击','通过Ｚ力量使得认真起来的卡比兽跃动巨大身躯，全力向对手发动袭击.',100,210,1,0,'普通','物攻'),
(702,'','九彩昇华齐聚顶','通过Ｚ力量使得认真起来的伊布跃动巨大身躯，全力向对手发动袭击.',150,0,1,0,'普通','其他'),
(703,'k,99999,k','起源超新星大爆炸','得到Ｚ力量的梦幻将全力攻击对手.脚下会变成精神场地.',100,185,1,0,'超能','特攻'),
(704,'k,776,k','陷阱甲壳','设下甲壳陷阱.如果对手使出物理招式，陷阱就会爆炸并给予对手伤害.',100,150,5,0,'火','特攻'),
(705,'k,801,k','花朵加农炮','放出强力光束后，自己的特攻会大幅降低.',100,130,5,0,'妖精','特攻'),
