(711,'k,800,k','棱镜镭射','用棱镜的力量发射强烈光线.下一回合自己将无法动弹.',100,160,10,0,'超能','特攻'),
(712,'k,802,k','暗影偷盗','潜入对手的影子进行攻击.会夺取对手的能力提升.',65,90,10,0,'幽灵','物攻'),
(713,'k,791,800,k','流星闪冲','以流星般的气势猛撞对手.可以无视对手的特性进行攻击.',80,100,5,0,'钢','物攻'),
(714,'k,792,800,k','暗影之光','放出奇怪的光线攻击对手.可以无视对手的特性进行攻击.',80,100,5,0,'幽灵','特攻'),
(715,'k,99999,k','泪眼汪汪','变得泪眼汪汪，让对手丧失斗志.从而降低对手的攻击和特攻.',150,0,20,0,'普通','其他'),
(716,'k,777,871,k','麻麻刺刺','撞向对手，并发出强电，使其感到麻麻刺刺的.有时会使对手畏缩.',70,80,10,0,'电','物攻'),
(717,'k,99999,k','自然之怒','向对手释放自然之怒.对手的ＨＰ会减半.',150,0,10,0,'妖精','特攻'),
(718,'k,773,k','多属性攻击','一边覆盖高能量，一边撞向对手进行攻击.根据存储碟不同，属性会改变.',65,120,10,0,'普通','物攻'),
(719,'k,99999,k','千万伏特','戴着帽子的皮卡丘将通过Ｚ力量增强的电击全力释放给对手.容易击中要害.',100,195,1,0,'电','特攻'),
