(796,'k,27,28,50,51,81,82,95,123,208,212,227,303,304,305,306,374,375,376,379,385,436,437,447,448,462,483,485,529,530,588,589,597,598,599,600,601,618,624,625,632,638,649,679,680,681,707,773,777,791,797,798,801,805,808,809,823,863,878,879,884,888,889,k','铁蹄光线','将从全身聚集的钢铁化为光束，激烈地发射出去。自己也会受到伤害。',80,140,10,0,'钢','特攻'),
(797,'k,39,40,63,64,65,79,80,102,103,120,121,122,124,150,151,177,178,196,199,251,280,281,282,343,344,374,375,376,385,436,437,475,480,481,482,488,494,517,518,527,528,554,555,561,574,575,576,577,578,579,605,606,677,678,686,687,765,791,792,800,806,825,826,856,857,858,866,876,898,k','广域战力','利用精神力量攻击对手。在精神场地上威力会有所提高，能对所有对手造成伤害。',30,80,10,0,'超能','特攻'),
(798,'k,99999,k','铁滚轮','可修改.请一定不要删除.作为预留技能空间',150,0,0,0,'钢','物攻'),
(799,'k,116,117,147,148,149,151,230,249,349,350,380,381,384,443,444,445,483,484,610,611,612,621,643,644,646,690,691,694,695,696,697,718,746,757,758,776,780,782,783,784,804,818,833,834,843,844,846,847,895,k','鳞射','发射鳞片进行攻击。连续攻击２～５次。速度会提高但防御会降低。',70,125,20,0,'龙','物攻'),
(800,'k,35,36,95,112,121,138,139,140,141,142,151,185,208,213,222,306,337,338,345,346,347,348,369,375,376,377,379,384,385,437,464,524,525,526,558,564,565,566,567,605,606,688,689,696,697,698,699,703,719,791,792,793,797,805,834,837,838,839,864,874,880,881,882,883,890,k','流星光束','第１回合聚集宇宙之力提高特攻，第２回合攻击对手。',70,120,10,0,'岩石','特攻'),
(801,'k,99999,k','臂贝武器','可修改.请一定不要删除.作为预留技能空间',150,0,0,0,'毒','特攻'),
(802,'k,35,36,39,40,151,183,184,280,281,282,517,518,682,683,684,685,700,703,716,719,730,801,858,869,k','薄雾炸裂','对自己周围的所有宝可梦进行攻击，但使出后，自己会陷入濒死。在薄雾场地上，招式威力会提高。',60,100,10,0,'妖精','特攻'),
(803,'k,1,2,3,43,44,45,102,103,114,151,182,251,252,253,254,270,271,272,273,274,275,315,406,407,420,421,459,460,465,470,546,547,548,549,556,640,708,709,710,711,722,723,724,753,754,761,762,763,764,781,810,811,812,829,830,831,832,840,841,842,865,893,k','青草滑梯','仿佛在地面上滑行般地攻击对手。在青草场地上，必定能够先制攻击。',20,70,20,0,'草','物攻'),
(804,'k,25,26,81,82,125,135,145,151,170,171,172,243,309,310,403,404,405,462,466,479,587,595,596,599,600,601,642,644,694,695,702,736,737,738,777,796,807,835,836,849,871,877,880,881,894,k','电力上升','用从地面升腾而起的电击进行攻击。当对手处于电气场地上时，招式威力会变成２倍。',80,140,20,0,'电','特攻'),
(805,'k,1,2,3,7,8,9,102,103,108,115,143,151,206,293,294,295,447,448,463,486,618,692,693,703,716,719,765,770,772,773,876,k','大地波动','借助场地的力量进行攻击。视使出招式时场地状态不同，招式的属性和威力会有所变化。',60,100,10,0,'普通','特攻'),
(806,'k,708,709,724,736,737,738,751,752,757,758,767,768,795,802,833,834,843,844,850,851,853,872,873,k','爬击','从对手背后爬近后进行攻击。会降低对手的特攻。',20,70,10,0,'虫','物攻'),
(807,'k,725,726,727,776,778,k','妒火','用嫉妒的能量攻击对手。会让在该回合内能力有所提高的宝可梦陷入灼伤状态。 ',20,70,10,0,'火','特攻'),
(808,'k,52,53,128,129,130,146,151,197,215,246,247,248,263,264,273,274,275,302,341,342,434,435,442,451,452,453,454,461,509,510,551,552,553,554,555,559,560,566,567,570,571,618,621,624,625,626,629,630,641,642,674,675,686,687,696,697,717,725,726,727,744,745,749,750,776,780,799,827,828,859,860,861,862,863,877,892,893,896,897,898,k','泄愤','攻击对手以发泄对其感到的恼怒情绪。如果在该回合内自身能力遭到降低，招式的威力会变成２倍。',85,150,10,0,'恶','物攻'),
(809,'k,92,93,94,151,292,302,355,356,442,477,478,479,487,562,563,592,593,607,608,609,622,623,708,709,710,711,724,769,770,781,792,802,854,855,864,867,k','灵骚','操纵对手的持有物进行攻击。当对手没有携带道具时，使出此招式时便会失败。 ',65,110,10,0,'幽灵','物攻'),
